// Marks each answer right or wrong against the reference SQL: every value in the reference result must
// appear in the assistant's result (numbers within 0.6% or 0.11 for rounding, text ignoring case, dates
// by day). Column names and order don't matter.
// ---- lib-ilf.js (included by build.py): shared helpers for the Ironleaf workflows ----
const TZ = 'Europe/London';
const esc = s => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const settingsOf = items => Object.fromEntries(items.map(i => i.json).filter(r => r && r.key).map(r => [r.key, r.value]));
const parseJson = (s, d) => { try { return typeof s === 'string' ? JSON.parse(s) : (s === null || s === undefined ? d : s); } catch (e) { return d; } };
const clip = (t, n) => { t = String(t || '').trim().replace(/\.$/, ''); return t.length <= n ? t : t.slice(0, n).replace(/\s+\S*$/, '') + '…'; };
const nowIso = () => DateTime.now().setZone(TZ).toISO();
function aiJson(res) {
  if (!res || res.error) return null;
  const msg = (res.output || []).find(o => o && o.type === 'message');
  const part = msg && (msg.content || []).find(c => c && c.type === 'output_text');
  let t = part ? part.text : null;
  if (typeof t === 'string') { try { t = JSON.parse(t); } catch (e) { t = null; } }
  return t && typeof t === 'object' ? t : null;
}
function emailHtml(company, paragraphs, extraHtml) {
  const p = paragraphs.filter(Boolean).map(t => '<p style="margin:0 0 14px;text-align:left">' + t + '</p>').join('');
  return '<div style="font-family:Helvetica,Arial,sans-serif;font-size:15px;line-height:1.55;color:#1c1f26;max-width:600px;text-align:left">'
    + '<div style="font-weight:800;font-size:13px;letter-spacing:1.5px;text-transform:uppercase;color:#d9480f;margin:0 0 18px">' + esc(company) + '</div>'
    + p + (extraHtml || '') + '</div>';
}
// ---- end lib-ilf.js ----
const qs = $('Questions').all().map(i => i.json);
const refs = $('Reference').all().map(i => i.json);
const gots = $('Ask Assistant').all().map(i => i.json);
const runId = 'E' + DateTime.now().setZone(TZ).toFormat('LLdd-HHmm');
const asList = r => Array.isArray(r) ? r : (typeof r === 'string' ? JSON.parse(r) : []);
const cells = rows => rows.flatMap(r => Object.values(r));
const isNum = v => typeof v === 'number' || (typeof v === 'string' && /^-?\d+(\.\d+)?$/.test(v.trim()));
const isDate = v => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}/.test(v);
const at = nowIso();
return qs.map((q, i) => {
  const expected = asList((refs[i] || {}).rows);
  const g = gots[i] || {};
  const got = g.ok ? asList(g.rows) : [];
  const gotCells = cells(got);
  const missing = [];
  for (const v of cells(expected)) {
    if (v === null) continue;
    let found;
    if (isNum(v)) { const n = Number(v); found = gotCells.some(x => isNum(x) && Math.abs(Number(x) - n) <= Math.max(0.11, Math.abs(n) * 0.006)); }
    else if (isDate(v)) found = gotCells.some(x => String(x).slice(0, 10) === v.slice(0, 10) || String(x).slice(0, 7) === v.slice(0, 7) && v.slice(8, 10) === '01');
    else found = gotCells.some(x => String(x).toLowerCase() === String(v).toLowerCase());
    if (!found) missing.push(v);
  }
  const pass = !!g.ok && expected.length > 0 && missing.length === 0;
  return { json: { run_id: runId, qid: q.qid, question: q.question, expected_json: JSON.stringify(expected), got_json: JSON.stringify(got.slice(0, 20)), sql: g.sql || '',
    pass, note: !g.ok ? (g.answer || 'no answer').slice(0, 200) : missing.length ? 'missing: ' + missing.slice(0, 5).join(', ') : '', ms: g.ms || 0, at } };
});

// The score.
const rows = $('Compare').all().map(i => i.json);
const passed = rows.filter(r => r.pass);
const ms = rows.map(r => r.ms).sort((a, b) => a - b);
return [{ json: { run_id: rows[0].run_id, questions: rows.length, passed: passed.length, accuracy_pct: Math.round(1000 * passed.length / rows.length) / 10,
  median_s: Math.round(ms[Math.floor(ms.length / 2)] / 100) / 10, failed: rows.filter(r => !r.pass).map(r => r.qid + ': ' + r.question + ' (' + r.note + ')') } }];
